import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    path_parts = os.path.split(upload_dir)
    if path_parts[0] == '':
        raise ValueError("upload_dir must be a non-empty string")
    if filename == '':
        raise ValueError("filename must be a non-empty string")
    safe_filename = os.path.join(upload_dir, filename)
    if os.path.islink(safe_filename):
        raise ValueError("filename must not be a symbolic link")
    if os.path.ismount(safe_filename):
        raise ValueError("filename must not be a mount point")
    if os.path.exists(safe_filename):
        raise ValueError("filename must be unique within upload_dir")
    return safe_filename
