import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    path_parts = os.path.split(upload_dir)
    while path_parts:
        if filename.startswith(path_parts[-1]):
            return os.path.join(*path_parts[:-1]) + filename
        path_parts = path_parts[:-1]
    raise ValueError("Filename would escape upload_dir")
